import { get } from './app'
import { authorizeUrl, codeFrom, readAuth, refreshFrom, settingsOf } from './google'
import { byDate, dueDate, dueLabel, pickList, readCache, slimTasks, tick } from './tasks'

// The bodies below are shaped as Google documents them: the token endpoint's
// (developers.google.com/identity/protocols/oauth2/native-app) and the Tasks
// API's (tasklists.list, tasks.list with a `fields` mask, tasks.patch).
const SIGNED_IN = {
  access_token: '1/fFAGRNJru1FTz70BzhT3Zg',
  expires_in: 3920,
  token_type: 'Bearer',
  scope: 'https://www.googleapis.com/auth/tasks',
  refresh_token: '1//xEoDL4iW3cxlI7yDbSRFYNG01kVKM2C-259HOF2aQbI',
}
const REFRESHED = {
  access_token: '1/fFAGRNJru1FTz70BzhT3Zg-new',
  expires_in: 3920,
  scope: 'https://www.googleapis.com/auth/tasks',
  token_type: 'Bearer',
}
const LISTS = {
  items: [
    { id: 'MDk4NzY1NDMyMTA', title: 'My Tasks' },
    { id: 'MTIzNDU2Nzg5MDE', title: 'Groceries' },
  ],
}
const TASKS = {
  items: [
    { id: 'c3ViMg', title: 'Oat milk', status: 'needsAction', parent: 'dGFzazI', position: '00000000000000000001' },
    { id: 'dGFzazI', title: 'Shopping', status: 'needsAction', due: '2026-11-28T00:00:00.000Z', position: '00000000000000000002' },
    { id: 'dGFzazE', title: 'Pay the rent', status: 'needsAction', due: '2026-11-25T00:00:00.000Z', position: '00000000000000000001' },
    { id: 'c3ViMQ', title: 'Lemons', status: 'needsAction', parent: 'dGFzazI', position: '00000000000000000000' },
    { id: 'dGFzazM', title: 'Book the dentist', status: 'needsAction', due: '2026-12-04T00:00:00.000Z', position: '00000000000000000003' },
    { id: 'b3JwaGFu', title: 'Under a finished task', status: 'needsAction', parent: 'ZG9uZQ', position: '00000000000000000000' },
    { id: 'ZW1wdHk', title: '', status: 'needsAction', position: '00000000000000000004' },
  ],
}

// Saturday 28 November 2026, 10:00 in the zone the test runs in.
const NOW = new Date(2026, 10, 28, 10, 0, 0).getTime()
function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// Every text in a drawn tree, joined (function components run as JSX is made).
function textOf(node: any): string {
  if (node === null || node === undefined || node === false || node === true) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textOf).join(' ')
  return textOf(node.props?.children)
}

const KEYS = { clientId: '123456789012-abc.apps.googleusercontent.com', clientSecret: 'GOCSPX-secret' }
const signedIn = (extra = {}) => ({
  ...KEYS,
  auth: { client: KEYS.clientId, access: 'ya29.old', expires: NOW + 3000 * 1000, refresh: SIGNED_IN.refresh_token, code: '4/0Acode', at: 1 },
  ...extra,
})
const form = (body: string) => {
  const out: Record<string, string> = {}
  for (const part of String(body || '').split('&')) {
    const [k, v] = part.split('=')
    out[decodeURIComponent(k)] = decodeURIComponent(v || '')
  }
  return out
}

// A Google that answers the token endpoint and the Tasks API as asked.
function google(answers: { token?: any; lists?: any; tasks?: any; patch?: (url: string, body: any) => any } = {}) {
  return mock.httpRequest((url: string, options: any) => {
    if (url.startsWith('https://oauth2.googleapis.com/token')) return answers.token ? answers.token(form(options.body)) : mock.json(REFRESHED)
    if (url.includes('/users/@me/lists')) return answers.lists || mock.json(LISTS)
    if (options.method === 'PATCH') return answers.patch ? answers.patch(url, JSON.parse(options.body)) : mock.json({ id: 'x', status: 'completed' })
    if (url.includes('/tasks?')) return answers.tasks || mock.json(TASKS)
    return mock.response(404, { error: { code: 404, message: 'Not Found', status: 'NOT_FOUND' } })
  })
}

describe('the sign-in', () => {
  it('links to Google with the Tasks scope, offline, and the loopback redirect', () => {
    const link = authorizeUrl(settingsOf(makeApp({ state: KEYS })))
    expect(link.startsWith('https://accounts.google.com/o/oauth2/v2/auth?')).toBe(true)
    expect(link).toContain('scope=https%3A%2F%2Fwww.googleapis.com%2Fauth%2Ftasks')
    expect(link).toContain('redirect_uri=http%3A%2F%2F127.0.0.1%3A8888')
    expect(link).toContain('access_type=offline')
    expect(link).toContain('prompt=consent')
    expect(link).toContain('client_id=123456789012-abc.apps.googleusercontent.com')
  })

  it('finds the code in the landed address, encoded or not, and a pasted refresh token', () => {
    expect(codeFrom('http://127.0.0.1:8888/?code=4/0AeanS0ab-cd_ef&scope=https://www.googleapis.com/auth/tasks')).toBe('4/0AeanS0ab-cd_ef')
    expect(codeFrom('http://127.0.0.1:8888/?iss=https%3A%2F%2Faccounts.google.com&code=4%2F0AeanS0ab&scope=x')).toBe('4/0AeanS0ab')
    expect(codeFrom('4/0AeanS0abcdefghijklmnopqrstu')).toBe('4/0AeanS0abcdefghijklmnopqrstu')
    expect(codeFrom('hello')).toBe('')
    expect(refreshFrom('1//0gLu5abcdefghijklmnopqrstuvwxyz')).toBe('1//0gLu5abcdefghijklmnopqrstuvwxyz')
  })

  it('trades a pasted address for a refresh token once, and empties the setting', () => {
    const http = google({ token: () => mock.json(SIGNED_IN) })
    const app = makeApp({ state: { ...KEYS, signIn: 'http://127.0.0.1:8888/?code=4/0AeanS0ab&scope=https://www.googleapis.com/auth/tasks' } })
    at(NOW, () => get(app, makeContext()))
    const trade = http.calls.find(([url, o]) => url.startsWith('https://oauth2.googleapis.com/token') && form(o.body).grant_type === 'authorization_code')
    expect(form(trade[1].body)).toEqual({
      client_id: KEYS.clientId, client_secret: 'GOCSPX-secret', grant_type: 'authorization_code', code: '4/0AeanS0ab', redirect_uri: 'http://127.0.0.1:8888',
    })
    expect(app.state.signIn).toBe('')
    expect(app.state.auth).toMatchObject({ refresh: SIGNED_IN.refresh_token, access: SIGNED_IN.access_token, code: '4/0AeanS0ab' })
    // The same address pushed again by the control plane is not traded again.
    app.state.signIn = 'http://127.0.0.1:8888/?code=4/0AeanS0ab&scope=https://www.googleapis.com/auth/tasks'
    const trades = () => http.calls.filter(([url, o]) => url.startsWith('https://oauth2') && form(o.body).grant_type === 'authorization_code').length
    at(NOW + 1000, () => get(app, makeContext()))
    expect(trades()).toBe(1)
  })

  it('says so when the Tasks permission was left unticked', () => {
    const http = google({ token: () => mock.json(SIGNED_IN) })
    const app = makeApp({ state: { ...KEYS, signIn: 'http://127.0.0.1:8888/?code=4/0AeanS0ab&scope=email%20profile' } })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Sign in to Google')
    expect(screen).toContain('not allowed to see your tasks')
    expect(http.calls.length).toBe(0)
  })

  it('refreshes an access token that ran out, keeping the refresh token Google did not resend', () => {
    const http = google()
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, expires: NOW - 1000 } }) })
    at(NOW, () => get(app, makeContext()))
    const refresh = http.calls.find(([url]) => url.startsWith('https://oauth2.googleapis.com/token'))
    expect(form(refresh[1].body)).toEqual({ client_id: KEYS.clientId, client_secret: 'GOCSPX-secret', grant_type: 'refresh_token', refresh_token: SIGNED_IN.refresh_token })
    expect(app.state.auth).toMatchObject({ access: REFRESHED.access_token, refresh: SIGNED_IN.refresh_token })
    // And the Tasks API is asked with the new one.
    const lists = http.calls.find(([url]) => url.includes('/users/@me/lists'))
    expect(lists[1].headers.Authorization).toBe(`Bearer ${REFRESHED.access_token}`)
  })

  it('keeps the newest refresh token when Google sends one, and when it says how long it lasts', () => {
    google({ token: () => mock.json({ ...REFRESHED, refresh_token: '1//rotated-token-abcdefghijk', refresh_token_expires_in: 604799 }) })
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, expires: NOW - 1000 } }) })
    at(NOW, () => get(app, makeContext()))
    expect(app.state.auth.refresh).toBe('1//rotated-token-abcdefghijk')
    expect(app.state.auth.ends).toBe(NOW + 604799 * 1000)
  })

  it('refreshes once on a 401 and asks again', () => {
    let lists = 0
    const http = mock.httpRequest((url: string, options: any) => {
      if (url.startsWith('https://oauth2.googleapis.com/token')) return mock.json(REFRESHED)
      if (url.includes('/users/@me/lists')) {
        lists++
        return options.headers.Authorization === 'Bearer ya29.old'
          ? mock.response(401, { error: { code: 401, message: 'Request had invalid authentication credentials.', status: 'UNAUTHENTICATED' } })
          : mock.json(LISTS)
      }
      return mock.json(TASKS)
    })
    const app = makeApp({ state: signedIn() })
    at(NOW, () => get(app, makeContext()))
    expect(lists).toBe(2)
    expect(readCache(app)!.tasks.length).toBe(6)
    expect(http.calls.filter(([url]) => url.startsWith('https://oauth2')).length).toBe(1)
  })

  it('shows the sign-in again, with why, when the refresh token was revoked, and keeps the last list', () => {
    google({ token: () => mock.response(400, { error: 'invalid_grant', error_description: 'Token has been expired or revoked.' }) })
    const cache = { at: NOW - 3600 * 1000, wanted: '', list: LISTS.items[0], lists: LISTS.items, listsAt: NOW, tasks: [{ id: 'a', title: 'Kept', due: '', parent: '' }], sign: '4/0Acode' }
    const app = makeApp({ state: signedIn({ auth: { ...signedIn().auth, expires: NOW - 1000 }, cache }) })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('Sign in to Google')
    expect(screen).toContain('Google ended this sign-in')
    expect(app.state.auth.refresh).toBeUndefined()
    expect(app.state.cache.tasks[0].title).toBe('Kept')
  })

  it('takes a refresh token pasted from the OAuth Playground', () => {
    const http = google()
    const app = makeApp({ state: { ...KEYS, signIn: '1//0gPlaygroundTokenabcdefghijklmnop' } })
    at(NOW, () => get(app, makeContext()))
    const refresh = http.calls.find(([url]) => url.startsWith('https://oauth2.googleapis.com/token'))
    expect(form(refresh[1].body).refresh_token).toBe('1//0gPlaygroundTokenabcdefghijklmnop')
    expect(app.state.auth).toMatchObject({ refresh: '1//0gPlaygroundTokenabcdefghijklmnop', access: REFRESHED.access_token })
    expect(app.state.signIn).toBe('')
  })
})

describe('the list', () => {
  it('reads the lists and the open tasks with little asked of Google', () => {
    const http = google()
    const app = makeApp({ state: signedIn() })
    at(NOW, () => get(app, makeContext()))
    const tasksCall = http.calls.find(([url]) => url.includes('/tasks?'))
    expect(tasksCall[0]).toBe(
      'https://tasks.googleapis.com/tasks/v1/lists/MDk4NzY1NDMyMTA/tasks?showCompleted=false&showHidden=false&maxResults=100&fields=items(id,title,status,due,parent,position),nextPageToken',
    )
    expect(tasksCall[1].headers.Authorization).toBe('Bearer ya29.old')
    const cache = readCache(app)!
    expect(cache.list.title).toBe('My Tasks')
    // Top level by position, each followed by its subtasks by theirs; one
    // whose parent is done goes last; a task with no title is left out.
    expect(cache.tasks.map((task) => task.title)).toEqual(['Pay the rent', 'Shopping', 'Lemons', 'Oat milk', 'Book the dentist', 'Under a finished task'])
    expect(cache.tasks[2]).toEqual({ id: 'c3ViMQ', title: 'Lemons', due: '', parent: 'dGFzazI' })
    expect(cache.tasks[1].due).toBe('2026-11-28')
    // Read again only when the interval is up.
    const calls = http.calls.length
    at(NOW + 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls)
    at(NOW + 900 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls + 1)
  })

  it('draws the tasks with their due dates and the tally', () => {
    google()
    const app = makeApp({ state: signedIn() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('My Tasks')
    expect(screen).toContain('Pay the rent')
    expect(screen).toContain('Lemons')
    expect(screen).toContain('Today')
    expect(screen).toContain('6 to do')
    expect(screen).toContain('1 late')
  })

  it('shows the list named in the setting, in any case, and says when there is none', () => {
    google()
    const groceries = makeApp({ state: signedIn({ list: 'groceries' }) })
    at(NOW, () => get(groceries, makeContext()))
    expect(readCache(groceries)!.list.title).toBe('Groceries')
    const missing = makeApp({ state: signedIn({ list: 'Work' }) })
    at(NOW, () => get(missing, makeContext()))
    expect(readCache(missing)!.list.title).toBe('My Tasks')
    expect(frameos.recall('problem')).toContain('no list called "Work"')
    expect(pickList(LISTS.items, '')).toEqual({ list: LISTS.items[0], missing: false })
  })

  it('keeps the last list when the network is down, and tries again sooner', () => {
    const cache = { at: NOW - 3600 * 1000, wanted: '', list: LISTS.items[0], lists: LISTS.items, listsAt: NOW, tasks: [{ id: 'a', title: 'Kept', due: '', parent: '' }], sign: '4/0Acode' }
    mock.httpRequest(() => ({ status: 0, error: 'connection refused' }))
    const app = makeApp({ state: signedIn({ cache }) })
    at(NOW, () => get(app, makeContext()))
    expect(app.state.cache.tasks[0].title).toBe('Kept')
    expect(frameos.recall('problem')).toContain('Could not reach Google')
    expect(app.nextSleep).toBe(60)
  })

  it('waits as long as Google asks when it is rate limited', () => {
    const http = google({
      lists: mock.response(429, { error: { code: 429, message: 'Quota exceeded', status: 'RESOURCE_EXHAUSTED' } }, { headers: { 'retry-after': '120' } }),
    })
    const cache = { at: NOW - 3600 * 1000, wanted: '', list: LISTS.items[0], lists: [], listsAt: 0, tasks: [{ id: 'a', title: 'Kept', due: '', parent: '' }], sign: '4/0Acode' }
    const app = makeApp({ state: signedIn({ cache }) })
    at(NOW, () => get(app, makeContext()))
    expect(frameos.recall('problem')).toContain('slow down')
    expect(app.nextSleep).toBe(121)
    const calls = http.calls.length
    at(NOW + 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(calls)
  })

  it('says how to turn the Tasks API on when it is off', () => {
    google({
      lists: mock.response(403, {
        error: {
          code: 403,
          message: 'Google Tasks API has not been used in project 123456789012 before or it is disabled.',
          status: 'PERMISSION_DENIED',
          details: [{ '@type': 'type.googleapis.com/google.rpc.ErrorInfo', reason: 'SERVICE_DISABLED', domain: 'googleapis.com' }],
        },
      }),
    })
    const app = makeApp({ state: signedIn() })
    const screen = textOf(at(NOW, () => get(app, makeContext())))
    expect(screen).toContain('turn it on')
  })

  it('picks another list on the frame: the setting follows, and that list is read', () => {
    const http = google()
    const app = makeApp({ state: signedIn() })
    const list = at(NOW, () => get(app, makeContext()))
    at(NOW + 1000, () => pressable(list, 'My Tasks').props.onClick({ x: 0, y: 0 }))
    const lists = at(NOW + 2000, () => get(app, makeContext()))
    expect(textOf(lists)).toContain('Task lists')
    at(NOW + 3000, () => pressable(lists, 'Groceries').props.onClick({ x: 0, y: 0 }))
    expect(app.state.list).toBe('Groceries')
    at(NOW + 4000, () => get(app, makeContext()))
    const last = http.calls[http.calls.length - 1][0]
    expect(last.startsWith('https://tasks.googleapis.com/tasks/v1/lists/MTIzNDU2Nzg5MDE/tasks?')).toBe(true)
    expect(readCache(app)!.list.title).toBe('Groceries')
  })
})

// The innermost element with a handler whose text holds this.
function pressable(tree: any, text: string): any {
  if (!tree || typeof tree !== 'object') return null
  if (Array.isArray(tree)) {
    for (const child of tree) {
      const found = pressable(child, text)
      if (found) return found
    }
    return null
  }
  const inside = pressable(tree.props?.children, text)
  if (inside) return inside
  return tree.props?.onClick && textOf(tree).includes(text) ? tree : null
}

describe('ticks', () => {
  const cacheOf = () => ({
    at: NOW, wanted: '', list: LISTS.items[0], lists: LISTS.items, listsAt: NOW, sign: '4/0Acode',
    tasks: slimTasks(TASKS),
  })
  // The element a tap on the row with this title reaches.
  function rowFor(tree: any, title: string): any {
    if (!tree || typeof tree !== 'object') return null
    if (Array.isArray(tree)) {
      for (const child of tree) {
        const found = rowFor(child, title)
        if (found) return found
      }
      return null
    }
    const inside = rowFor(tree.props?.children, title)
    if (inside) return inside
    return tree.props?.onClick && textOf(tree).includes(title) ? tree : null
  }

  it('ticks a task off from a tap: a PATCH to completed, its subtasks with it', () => {
    const patches: any[] = []
    google({ patch: (url, body) => { patches.push([url, body]); return mock.json({ ...body, id: url.split('/').pop() }) } })
    const app = makeApp({ state: signedIn({ cache: cacheOf() }) })
    const tree = at(NOW, () => get(app, makeContext()))
    at(NOW + 1000, () => rowFor(tree, 'Shopping').props.onClick({ x: 0, y: 0 }))
    expect(patches.map(([url]) => url.split('/').pop())).toEqual(['dGFzazI', 'c3ViMQ', 'c3ViMg'])
    expect(patches[0]).toEqual(['https://tasks.googleapis.com/tasks/v1/lists/MDk4NzY1NDMyMTA/tasks/dGFzazI', { status: 'completed' }])
    expect(app.state.cache.tasks.filter((task) => task.done).map((task) => task.title)).toEqual(['Shopping', 'Lemons', 'Oat milk'])
    // The next whole render draws them ticked, and counts them done.
    const after = textOf(at(NOW + 2000, () => get(app, makeContext())))
    expect(after).toContain('3 to do')
  })

  it('puts a tick back when Google refuses it, and says so', () => {
    google({ patch: () => mock.response(404, { error: { code: 404, message: 'Not Found', status: 'NOT_FOUND' } }) })
    const app = makeApp({ state: signedIn({ cache: cacheOf() }) })
    const tree = at(NOW, () => get(app, makeContext()))
    at(NOW + 1000, () => rowFor(tree, 'Shopping').props.onClick({ x: 0, y: 0 }))
    expect(app.state.cache.tasks.filter((task) => task.done)).toEqual([])
    const after = textOf(at(NOW + 2000, () => get(app, makeContext())))
    expect(after).toContain('Could not tick off "Shopping"')
    expect(after).toContain('6 to do')
  })

  it('keeps the subtasks Google took when one of them is refused', () => {
    google({
      patch: (url, body) => (url.endsWith('c3ViMg') ? { status: 0, error: 'timed out' } : mock.json(body)),
    })
    const app = makeApp({ state: signedIn() })
    const cache = cacheOf()
    const result = tick({ app, s: settingsOf(app), token: 'ya29.old' }, cache, 'dGFzazI', true)
    expect(result.changed.map((task) => task.title)).toEqual(['Shopping', 'Lemons'])
    expect(result.problem).toContain('Could not tick off "Oat milk". Could not reach Google')
    expect(cache.tasks.find((task) => task.title === 'Oat milk')!.done).toBeUndefined()
  })

  it('reopens a task ticked by mistake', () => {
    const patches: any[] = []
    google({ patch: (url, body) => { patches.push(body); return mock.json(body) } })
    const app = makeApp({ state: signedIn() })
    const cache = cacheOf()
    cache.tasks[0].done = true
    const result = tick({ app, s: settingsOf(app), token: 'ya29.old' }, cache, 'dGFzazE', false)
    expect(result.problem).toBe('')
    expect(patches).toEqual([{ status: 'needsAction', completed: null }])
    expect(cache.tasks[0].done).toBe(false)
  })

  it('says why when Google is asked to wait', () => {
    google()
    const app = makeApp({ state: signedIn() })
    frameos.remember('wait', NOW + 60 * 1000)
    const result = at(NOW, () => tick({ app, s: settingsOf(app), token: 'ya29.old' }, cacheOf(), 'dGFzazE', true))
    expect(result.problem).toContain('slow down')
  })
})

describe('due dates', () => {
  it('reads the date off the text, whatever the zone', () => {
    expect(dueDate('2026-12-01T00:00:00.000Z')).toBe('2026-12-01')
    expect(dueDate(undefined)).toBe('')
  })

  it('is as short as it reads', () => {
    expect(dueLabel('2026-11-28', '2026-11-28')).toEqual({ text: 'Today', late: false, today: true })
    expect(dueLabel('2026-11-29', '2026-11-28')!.text).toBe('Tomorrow')
    expect(dueLabel('2026-11-27', '2026-11-28')).toEqual({ text: 'Yesterday', late: true, today: false })
    expect(dueLabel('2026-12-02', '2026-11-28')!.text).toBe('Wed')
    expect(dueLabel('2026-11-03', '2026-11-28')).toEqual({ text: 'Nov 3', late: true, today: false })
    expect(dueLabel('2027-01-15', '2026-11-28')!.text).toBe('Jan 15 2027')
  })

  it('sorts by date with each task keeping its subtasks', () => {
    const order = byDate(slimTasks(TASKS)).map((task) => task.title)
    expect(order).toEqual(['Pay the rent', 'Shopping', 'Lemons', 'Oat milk', 'Book the dentist', 'Under a finished task'])
  })
})

