// @name Google Tasks
// @background #f6f8fc
// @refresh 900
// The open tasks of one Google Tasks list, with their due dates and their
// subtasks. Tap a task to tick it off: it is ticked in the kept list, Google
// is told at once, and what Google refuses is put back with a message. A
// ticked task stays, struck through, until the next read; tap it to reopen
// it. The list is read again every
// 15 minutes (the scene's refresh interval), and the last one read is kept
// on the frame's disk, so it stays up through a lost network or a restart.
//
// google.ts signs in and talks to Google, tasks.ts keeps the list and sends
// the ticks, ui.tsx has the looks and the setup screens.
import { authorizeUrl, newRender, readAuth, session, settingsOf, waitUntil } from './google'
import type { Client, Settings } from './google'
import { byDate, dueLabel, readCache, refresh, tick, todayOf } from './tasks'
import type { Cache, List, Task } from './tasks'
import { Banner, BigButton, Icon, SetupScreen, sizesOf, themeOf } from './ui'
import type { Sizes, Theme } from './ui'

// A message about a tick stays this long.
const NOTE_MS = 20000

// ---------------------------------------------------------------- what a tap changes

// The tasks drawn, in the order drawn, and a signal per row for its tick. A
// tap ticks the task in the kept list, tells Google at once, and sets the
// signals of the rows it ticked and of the tally, so only those redraw (the
// frame shows a press itself while Google answers). When Google refuses, the
// tick is put back and no signal is set: the whole page draws again, with
// the message.
let shown: Task[] = []
let kept: Cache | null = null
let appNow: any = null
const rows: { done: any }[] = []
const row = (i: number) => (rows[i] ??= { done: signal(false) })
const openCount = signal(0)
const lateCount = signal(0)
const todayCount = signal(0)
let today = ''

function tally() {
  let open = 0
  let late = 0
  let due = 0
  shown.forEach((task, i) => {
    if (row(i).done.peek()) return
    open++
    const label = dueLabel(task.due, today)
    if (label?.late) late++
    else if (label?.today) due++
  })
  openCount.value = open
  lateCount.value = late
  todayCount.value = due
}

function toggle(i: number) {
  const task = shown[i]
  if (!task || !kept || !appNow) return
  const s = settingsOf(appNow)
  const now = session(appNow, s)
  if (!now.token) {
    note(`Could not tell Google: ${now.problem || 'signed out'}`)
    return
  }
  const result = tick({ app: appNow, s, token: now.token }, kept, task.id, !row(i).done.peek())
  if (result.problem) {
    note(result.problem)
    return
  }
  for (const one of result.changed) {
    const j = shown.findIndex((other) => other.id === one.id)
    if (j >= 0) row(j).done.value = !!one.done
  }
  tally()
}

// The list picked on the frame: kept in the Task list setting, and here
// until that setting says so (a handler's setState shows by the next render).
function chooseList(title: string) {
  frameos.remember('pick', { title, at: Date.now() })
  frameos.setState('list', title)
  frameos.remember('view', null)
  frameos.remember('force', true)
}
const openLists = () => frameos.remember('view', 'lists')
const closeLists = () => frameos.remember('view', null)
const readAgain = () => frameos.remember('force', true)

function note(text: string) {
  frameos.remember('note', text ? { text, at: Date.now() } : null)
}
function noteNow(): string {
  const kept: any = frameos.recall('note')
  return kept && Date.now() - kept.at < NOTE_MS ? String(kept.text) : ''
}

// ---------------------------------------------------------------- keys

export function onEvent(app, context) {
  if (context.event === 'back' && frameos.recall('view') === 'lists') {
    closeLists()
    return true
  }
  return false
}

// ---------------------------------------------------------------- parts

const Tick = ({ t, z, on, size }: { t: Theme; z: Sizes; on: boolean; size: number }) => (
  <div className={`w-[${z.s(size)}px] h-[${z.s(size)}px] shrink-0 rounded-full flex items-center justify-center ${on ? t.circleOn : t.circle}`}>
    {on ? <Icon name="check" size={z.s(size * 0.7)} width={3} /> : null}
  </div>
)

// One task: its tick, its title, and its due date under it. A subtask is
// set in, with a smaller tick. A tap anywhere on it ticks it.
const Row = memo(({ i, t, z, title, sub, due, kind, tight }: {
  i: number; t: Theme; z: Sizes; title: string; sub: boolean; due: string; kind: string; tight: boolean
}) => {
  const done = rows[i].done.value
  const chip = done ? t.chip : kind === 'late' ? t.chipLate : kind === 'today' ? t.chipToday : t.chip
  return (
    <div className={`flex items-start gap-[${z.s(12)}px] ${sub ? `pl-[${z.s(tight ? 30 : 40)}px]` : `pl-[${z.s(4)}px]`} pr-[${z.s(4)}px] py-[${z.s(tight ? 8 : 11)}px] ${t.line}`}
      onClick={() => toggle(i)}>
      <div className={`pt-[${z.s(1)}px]`}>
        <Tick t={t} z={z} on={done} size={sub ? 20 : 24} />
      </div>
      <div className={`flex-1 min-w-0 flex flex-col gap-[${z.s(5)}px]`}>
        <span className={`text-[${z.s(sub ? 16 : 18)}px] leading-snug line-clamp-2 ${done ? t.doneText : ''}`}>{title}</span>
        {due ? (
          <div className={`self-start flex items-center gap-[${z.s(5)}px] rounded-full px-[${z.s(9)}px] py-[${z.s(2)}px] text-[${z.s(13)}px] ${chip}`}>
            <Icon name="calendar" size={z.s(13)} />
            <span>{due}</span>
          </div>
        ) : null}
      </div>
    </div>
  )
})

// "7 to do · 2 late · 1 today", from the signals.
const TallyLine = memo(({ t, z, size }: { t: Theme; z: Sizes; size: number }) => {
  const parts = [openCount.value ? `${openCount.value} to do` : 'All done']
  return (
    <div className={`flex items-center gap-[${z.s(8)}px] text-[${z.s(size)}px] ${t.muted}`}>
      <span>{parts[0]}</span>
      {lateCount.value ? <span className={`font-bold ${t.late}`}>{`${lateCount.value} late`}</span> : null}
      {todayCount.value ? <span className={`font-bold ${t.accent}`}>{`${todayCount.value} today`}</span> : null}
    </div>
  )
})

// The side panel's tally: the number to do, large, and what is late or due.
const BigTally = memo(({ t, z }: { t: Theme; z: Sizes }) => (
  <div className={`flex flex-col gap-[${z.s(4)}px]`}>
    <div className="flex items-end gap-[8px]">
      <span className={`text-[${z.s(64)}px] font-bold leading-none`}>{String(openCount.value)}</span>
      <span className={`text-[${z.s(18)}px] pb-[${z.s(6)}px] ${t.muted}`}>to do</span>
    </div>
    {lateCount.value ? <span className={`text-[${z.s(17)}px] font-bold ${t.late}`}>{`${lateCount.value} late`}</span> : null}
    {todayCount.value ? <span className={`text-[${z.s(17)}px] font-bold ${t.accent}`}>{`${todayCount.value} due today`}</span> : null}
  </div>
))

function ListName({ t, z, title, many, size }: { t: Theme; z: Sizes; title: string; many: boolean; size: number }) {
  return (
    <div className={`flex items-center min-w-0 gap-[${z.s(6)}px]`} onClick={many ? openLists : undefined}>
      <span className={`text-[${z.s(size)}px] font-bold leading-tight truncate`}>{title}</span>
      {many ? <Icon name="chevron" size={z.s(size * 0.8)} /> : null}
    </div>
  )
}

function RefreshButton({ t, z }: { t: Theme; z: Sizes }) {
  return (
    <div className={`w-[${z.s(44)}px] h-[${z.s(44)}px] shrink-0 rounded-full flex items-center justify-center ${t.button}`} onClick={readAgain}>
      <Icon name="refresh" size={z.s(22)} />
    </div>
  )
}

function Empty({ t, z, list }: { t: Theme; z: Sizes; list: string }) {
  return (
    <div className={`flex-1 flex flex-col items-center justify-center gap-[${z.s(10)}px] p-[${z.s(16)}px]`}>
      <div className={`w-[${z.s(64)}px] h-[${z.s(64)}px] rounded-full flex items-center justify-center ${t.circleOn}`}>
        <Icon name="check" size={z.s(36)} width={3} />
      </div>
      <span className={`text-[${z.s(22)}px] font-bold text-center`}>All done</span>
      <span className={`text-[${z.s(15)}px] text-center ${t.muted}`}>{`Nothing left on ${list}.`}</span>
    </div>
  )
}

const clock = (at: number) => {
  const d = new Date(at)
  return `${d.getHours()}:${String(d.getMinutes()).padStart(2, '0')}`
}
const updatedText = (cache: Cache) => {
  const day = todayOf(cache.at) === today ? '' : ` on ${todayOf(cache.at).slice(5).replace('-', '/')}`
  return `Updated ${clock(cache.at)}${day}`
}

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

// ---------------------------------------------------------------- the screens

type View = { t: Theme; z: Sizes; W: number; H: number; cache: Cache; problem: string; tight: boolean }

function rowsOf(v: View) {
  return shown.map((task, i) => {
    const label = dueLabel(task.due, today)
    return (
      <Row i={i} t={v.t} z={v.z} title={task.title} sub={!!task.parent} due={label ? label.text : ''}
        kind={label ? (label.late ? 'late' : label.today ? 'today' : '') : ''} tight={v.tight} />
    )
  })
}

function listBox(v: View, className: string) {
  if (!shown.length) return <Empty t={v.t} z={v.z} list={v.cache.list.title} />
  return (
    <div className={`flex-1 min-h-0 overflow-y-auto ${className}`}>
      <div className="flex flex-col">
        {rowsOf(v)}
        {v.cache.more ? <span className={`py-[${v.z.s(10)}px] text-[${v.z.s(14)}px] text-center ${v.t.muted}`}>More tasks in Google Tasks</span> : null}
      </div>
    </div>
  )
}

// A wide panel: the day and the tally at the side, the list beside them.
function wide(v: View) {
  const { t, z, cache } = v
  const now = new Date()
  return (
    <div className={`flex w-full h-full ${t.page}`}>
      <div className={`flex flex-col w-[32%] shrink-0 gap-[${z.s(18)}px] p-[${z.s(24)}px] ${t.side}`}>
        <div className="flex flex-col">
          <span className={`text-[${z.s(18)}px] ${t.muted}`}>{WEEKDAYS[now.getDay()]}</span>
          <span className={`text-[${z.s(30)}px] font-bold leading-tight`}>{`${MONTH_NAMES[now.getMonth()]} ${now.getDate()}`}</span>
        </div>
        <ListName t={t} z={z} title={cache.list.title} many={cache.lists.length > 1} size={20} />
        <BigTally t={t} z={z} />
        <div className="flex-1" />
        <div className={`flex items-center gap-[${z.s(4)}px]`}>
          <span className={`flex-1 min-w-0 text-[${z.s(13)}px] ${t.muted}`}>{updatedText(cache)}</span>
          <RefreshButton t={t} z={z} />
        </div>
      </div>
      <div className={`flex-1 min-w-0 flex flex-col gap-[${z.s(10)}px] px-[${z.s(20)}px] py-[${z.s(12)}px]`}>
        {v.problem ? <Banner t={t} z={z} text={v.problem} onClose={() => note('')} /> : null}
        {listBox(v, '')}
      </div>
    </div>
  )
}

// A tall or square panel: the list's name and the tally on top.
function tall(v: View) {
  const { t, z, cache, tight } = v
  return (
    <div className={`flex flex-col w-full h-full gap-[${z.s(tight ? 8 : 12)}px] p-[${z.s(tight ? 12 : 20)}px] ${t.page}`}>
      <div className={`flex items-center gap-[${z.s(8)}px]`}>
        <div className="flex-1 min-w-0 flex flex-col">
          <ListName t={t} z={z} title={cache.list.title} many={cache.lists.length > 1} size={tight ? 22 : 28} />
          <TallyLine t={t} z={z} size={tight ? 14 : 16} />
        </div>
        <RefreshButton t={t} z={z} />
      </div>
      {v.problem ? <Banner t={t} z={z} text={v.problem} onClose={() => note('')} /> : null}
      <div className={`flex-1 min-h-0 flex flex-col rounded-[${z.s(16)}px] px-[${z.s(tight ? 8 : 12)}px] ${t.card}`}>
        {listBox(v, '')}
      </div>
      <span className={`text-[${z.s(12)}px] text-center ${t.muted}`}>{updatedText(cache)}</span>
    </div>
  )
}

// A round panel: the list's name and the tally in the arc at the top, the
// list as wide as the circle lets it be, Updated and the refresh button in
// the arc at the bottom.
function round(v: View) {
  const { t, z, cache, W, H } = v
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const headTop = Math.round(R * 0.9)
  const headW = chord(headTop - 20)
  const listTop = Math.round(R * 0.55)
  const listBottom = Math.round(R * 0.6)
  const listW = Math.min(chord(listTop), chord(listBottom))
  const footTop = listBottom + 8
  const footW = chord(footTop + 44)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${Math.round(cx - headW / 2)}px] top-[${Math.round(cy - headTop)}px] w-[${headW}px] flex flex-col items-center`}>
        <ListName t={t} z={z} title={cache.list.title} many={cache.lists.length > 1} size={24} />
        <TallyLine t={t} z={z} size={15} />
      </div>
      <div className={`absolute left-[${Math.round(cx - listW / 2)}px] top-[${Math.round(cy - listTop)}px] w-[${listW}px] h-[${listTop + listBottom}px] flex flex-col gap-[6px]`}>
        {v.problem ? <Banner t={t} z={z} text={v.problem} onClose={() => note('')} /> : null}
        {listBox(v, '')}
      </div>
      <div className={`absolute left-[${Math.round(cx - footW / 2)}px] top-[${Math.round(cy + footTop)}px] w-[${footW}px] flex items-center justify-center gap-[4px]`}>
        <span className={`text-[${z.s(13)}px] ${t.muted}`}>{updatedText(cache)}</span>
        <RefreshButton t={t} z={z} />
      </div>
    </div>
  )
}

// The task lists of the account, to pick the one the frame shows.
function listsScreen(t: Theme, z: Sizes, cache: Cache, inSquare: (ui: any) => any) {
  return inSquare(
    <div className={`flex flex-col w-full h-full gap-[${z.s(12)}px] p-[${z.s(16)}px] ${t.page}`}>
      <div className={`flex items-center gap-[${z.s(8)}px]`}>
        <div className={`w-[${z.s(44)}px] h-[${z.s(44)}px] shrink-0 rounded-full flex items-center justify-center ${t.button}`} onClick={closeLists}>
          <Icon name="back" size={z.s(24)} />
        </div>
        <span className={`text-[${z.s(24)}px] font-bold`}>Task lists</span>
      </div>
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`flex flex-col gap-[${z.s(8)}px]`}>
          {cache.lists.map((list: List) => (
            <div className={`flex items-center gap-[${z.s(12)}px] h-[${z.s(52)}px] px-[${z.s(16)}px] rounded-[${z.s(14)}px] ${list.id === cache.list.id ? t.pillOn : t.pill}`}
              onClick={() => chooseList(list.title)}>
              <Icon name="list" size={z.s(20)} />
              <span className={`flex-1 min-w-0 text-[${z.s(18)}px] truncate`}>{list.title}</span>
              {list.id === cache.list.id ? <Icon name="check" size={z.s(20)} width={3} /> : null}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- the screens before the list

type Fit = { tight?: boolean; round?: { W: number; H: number } }

function setupScreen(t: Theme, z: Sizes, fit: Fit) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="tasks" title="Connect Google Tasks"
      intro="This list talks to Google through a sign-in client of your own. It takes a few minutes, once."
      steps={[
        {
          head: 'Make a Google Cloud project',
          text: 'On console.cloud.google.com, make a project. In APIs & Services, Library, turn on the Google Tasks API.',
        },
        {
          head: 'Set up its sign-in',
          text: 'In Google Auth Platform: Branding (any app name, your email), Audience: External, and add your Google account as a test user.',
        },
        {
          head: 'Make a Desktop app client',
          text: "Clients, Create client, Desktop app. Copy its Client ID and Client secret into this scene's settings, and save.",
        },
      ]}
      note="An app in Testing gets sign-ins that end after 7 days. To stay signed in, publish it (Audience, Publish app): Google then says it has not verified the app, which is yours, so press Advanced and go on." />
  )
}

function signInScreen(t: Theme, z: Sizes, fit: Fit, s: Settings, problem: string) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="key" title="Sign in to Google" problem={problem}
      intro="Let this frame see your tasks and tick them off."
      steps={[
        {
          head: 'Tap Sign in',
          text: "Scan its QR code with your phone (the editor's preview opens a tab instead), pick your account and allow Google Tasks.",
        },
        {
          head: 'Copy the address',
          text: 'The browser then fails to open a page. That is expected: copy its whole address, which starts with',
          code: `${s.redirectUri.replace(/\/$/, '')}/?`,
        },
        {
          head: 'Paste it into Sign-in address',
          text: "In this scene's settings, and save. The frame signs in with it and stays signed in.",
        },
      ]}
      action={<BigButton t={t} z={z} icon="link" label="Sign in" href={authorizeUrl(s)} />}
      note="In Testing, Google ends the sign-in after 7 days: publish the app to stay signed in." />
  )
}

function troubleScreen(t: Theme, z: Sizes, fit: Fit, problem: string) {
  return (
    <SetupScreen t={t} z={z} {...fit} icon="alert" title="No tasks yet" problem={problem}
      intro="" steps={[{ head: 'The frame tries again', text: 'On its own in a minute or two, or now with Try again.' }]}
      action={<BigButton t={t} z={z} icon="refresh" label="Try again" onClick={readAgain} />} />
  )
}

// ---------------------------------------------------------------- the scene

export function get(app, context) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const isRound = context?.round === true
  const t = themeOf(app)
  const now = Date.now()
  today = todayOf(now)
  // On a round panel the setup screens and the lists use the circle and the
  // square inside it.
  const side = isRound ? Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2) : 0
  const inSquare = (ui: any) =>
    isRound ? (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-[${(W - side) >> 1}px] top-[${(H - side) >> 1}px] w-[${side}px] h-[${side}px]`}>{ui}</div>
      </div>
    ) : ui
  const z = sizesOf(W, H)
  // A tall panel sets the setup screens a little larger: its height has the room.
  const zSetup = !isRound && H >= W * 1.25 && z.k === 1 ? sizesOf(W, H, Math.min(1.3, W / 400, H / 640)) : z
  const fit: Fit = isRound ? { round: { W, H } } : { tight: H < 400 }
  const interval = Math.max(60, Number(app.state.refreshInterval) || 900)

  newRender()
  const s = settingsOf(app)
  // Nothing changes on these screens until the settings do (a save renders).
  if (!s.clientId || !s.clientSecret) {
    frameos.setNextSleep(3600)
    return setupScreen(t, zSetup, fit)
  }
  const current = session(app, s)
  if (!current.signedIn) {
    frameos.setNextSleep(3600)
    return signInScreen(t, zSetup, fit, s, current.problem)
  }
  const client: Client | null = current.token ? { app, s, token: current.token } : null
  const auth = readAuth(app)

  // The list wanted: one picked on the frame a moment ago, else the setting.
  const pick: any = frameos.recall('pick')
  const setting = String(app.state.list ?? '').trim()
  let wanted = setting
  if (pick && pick.title !== setting && now - pick.at < 120000) wanted = String(pick.title)
  else if (pick) frameos.remember('pick', null)

  // The last good list, unless it was read for another sign-in.
  let cache = readCache(app)
  if (cache && (cache as any).sign !== auth.code) cache = null
  let problem = ''

  // Read the list when it is due (the scene's interval), asked for, or
  // another list is wanted. A failure keeps the last good one.
  const force = !!frameos.recall('force')
  const due = !cache || now - cache.at >= interval * 1000 - 30000 || cache.wanted !== wanted
  let failed = false
  if (client && (due || force) && waitUntil() <= now) {
    frameos.remember('force', null)
    const read = refresh(client, cache, wanted)
    if (read.cache && read.cache !== cache) {
      ;(read.cache as any).sign = auth.code
      cache = read.cache
      frameos.setState('cache', cache as any)
    }
    problem = read.problem || (read.missing ? `There is no list called "${read.missing}": showing ${cache?.list.title}.` : '')
    failed = !!read.problem
    frameos.remember('problem', problem)
    frameos.remember('fails', failed ? Number(frameos.recall('fails') || 0) + 1 : 0)
    // The sign-in ended during that read: a 401 the refresh could not mend.
    const after = readAuth(app)
    if (!after.refresh) return signInScreen(t, zSetup, fit, s, after.error || '')
  } else {
    if (force) frameos.remember('force', null)
    problem = String(frameos.recall('problem') || '')
    if (!client && current.problem) problem = current.problem
    failed = !!problem
  }
  problem = noteNow() || problem

  // When to look again: the scene's interval, sooner after a failure (one,
  // two, four, eight minutes), and not before Google's "slow down" is over.
  const wait = waitUntil()
  if (wait > now) frameos.setNextSleep(Math.min(interval, (wait - now) / 1000 + 1))
  else if (failed) frameos.setNextSleep(Math.min(interval, 60 * 2 ** Math.min(4, Math.max(0, Number(frameos.recall('fails') || 1) - 1))))

  if (!cache) return troubleScreen(t, z, fit, problem || 'Reading your tasks...')

  // What shows: the kept list, in the order asked for.
  kept = cache
  appNow = app
  shown = app.state.order === 'date' ? byDate(cache.tasks) : cache.tasks
  shown.forEach((task, i) => {
    row(i).done.value = !!task.done
  })
  tally()

  if (frameos.recall('view') === 'lists' && cache.lists.length > 1) return listsScreen(t, z, cache, inSquare)
  const v: View = { t, z, W, H, cache, problem, tight: z.small || H < 400 }
  if (isRound) return round({ ...v, tight: true })
  if (W >= H * 1.3 && W >= 640) return wide(v)
  return tall(v)
}

