// Talking to Google: the sign-in and the Tasks API calls the scene makes.
//
// The sign-in is the person's own OAuth client (a "Desktop app" client in
// the Google Cloud console): its Client ID and secret are in the scene's
// settings, and the address Google sends the browser to after "Continue" is
// pasted back into the Sign-in address setting. Its code is traded here for
// a refresh token, kept in the scene's private `auth` state (on the frame's
// disk, never shown in its settings), and an access token is made from it
// whenever the last one is about to run out (an hour each). A refresh token
// made elsewhere (Google's OAuth 2.0 Playground, with the same client) can
// be pasted into the same setting instead. Nothing goes through a FrameOS
// server.

export const AUTHORIZE = 'https://accounts.google.com/o/oauth2/v2/auth'
export const TOKEN = 'https://oauth2.googleapis.com/token'
export const API = 'https://tasks.googleapis.com/tasks/v1'

// See, edit, create and delete the person's tasks: ticking one off is an edit.
export const SCOPE = 'https://www.googleapis.com/auth/tasks'

// A Desktop app client takes any loopback address without registering it.
export const DEFAULT_REDIRECT = 'http://127.0.0.1:8888'

export type Settings = { clientId: string; clientSecret: string; redirectUri: string; signIn: string }

export function settingsOf(app): Settings {
  const text = (key: string) => String(app.state[key] ?? '').trim()
  return {
    clientId: text('clientId'),
    clientSecret: text('clientSecret'),
    redirectUri: text('redirectUri') || DEFAULT_REDIRECT,
    signIn: text('signIn'),
  }
}

export const query = (values: Record<string, string>) =>
  Object.keys(values).map((key) => `${key}=${encodeURIComponent(values[key])}`).join('&')

// The page that asks the person to let the frame in. It holds no secret and
// no state of the frame's, so the same link works wherever it is opened: the
// frame's QR code, or the editor's preview, which opens it in a tab.
// `prompt=consent` makes Google hand out a refresh token every time.
export function authorizeUrl(s: Settings) {
  return `${AUTHORIZE}?${query({
    response_type: 'code',
    client_id: s.clientId,
    redirect_uri: s.redirectUri,
    scope: SCOPE,
    access_type: 'offline',
    prompt: 'consent',
  })}`
}

const decoded = (text: string) => {
  try {
    return decodeURIComponent(text)
  } catch (e) {
    return text
  }
}

// The code in what was pasted: the whole address the browser ended on
// (http://127.0.0.1:8888/?code=4/0Ab...&scope=...), or the code alone.
export function codeFrom(text: string) {
  const found = /[?&#]code=([^&#\s]+)/.exec(text)
  if (found) return decoded(found[1])
  return /^\d\/[A-Za-z0-9_-]{20,}$/.test(text) ? text : ''
}

// A refresh token pasted as it is (they start with "1//").
export function refreshFrom(text: string) {
  return /^1\/\/[A-Za-z0-9_-]{20,}$/.test(text) ? text : ''
}

// The scopes the landed address says were granted, '' when it does not say.
export function scopeIn(text: string) {
  const found = /[?&#]scope=([^&#\s]*)/.exec(text)
  return found ? decoded(found[1].replace(/\+/g, ' ')) : ''
}
const deniedIn = (text: string) => /[?&#]error=access_denied/.test(text)

// ---------------------------------------------------------------- the sign-in

// What the scene keeps on the frame's disk. `client` is the Client ID it was
// made with (another one signs out), `code` the last pasted code or token (a
// code works once: the same one pasted again, or pushed again by the control
// plane, is not traded twice), `ends` when Google said the refresh token
// runs out (apps in Testing: seven days), `at` when it was written.
export type Auth = {
  client?: string
  access?: string
  expires?: number
  refresh?: string
  ends?: number
  code?: string
  error?: string
  at?: number
}

// The newest auth this render wrote: frameos.setState shows in app.state by
// the next render. get() forgets it as it starts (newRender), when app.state
// has it.
let written: Auth | null = null
export function newRender() {
  written = null
}

export function readAuth(app): Auth {
  let saved = app.state.auth
  if (typeof saved === 'string') {
    try {
      saved = saved ? JSON.parse(saved) : {}
    } catch (e) {
      saved = {}
    }
  }
  const stored: Auth = saved && typeof saved === 'object' ? saved : {}
  return written && (written.at || 0) >= (stored.at || 0) ? written : stored
}

function writeAuth(auth: Auth) {
  auth.at = Date.now()
  written = auth
  frameos.setState('auth', auth as any)
}

type TokenReply = { ok: boolean; data?: any; error?: string; code?: string; status?: number }

function tokenRequest(s: Settings, form: Record<string, string>): TokenReply {
  const reply = frameos.httpRequest(TOKEN, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
    body: query({ client_id: s.clientId, client_secret: s.clientSecret, ...form }),
    timeoutMs: 10000,
  })
  if (!reply.status) return { ok: false, error: `Could not reach Google: ${reply.error || 'no answer'}` }
  let data: any = null
  try {
    data = reply.body ? JSON.parse(reply.body) : null
  } catch (e) {
    data = null
  }
  if (reply.status === 200 && data && data.access_token) return { ok: true, data }
  const code = String(data?.error || '')
  const said = String(data?.error_description || '')
  return { ok: false, code, status: reply.status, error: tokenProblem(code, said, reply.status, form.grant_type) }
}

// What a refusal at the token endpoint means to a person.
function tokenProblem(code: string, said: string, status: number, grant: string) {
  if (code === 'invalid_client')
    return 'Google does not know this Client ID and Client secret: copy both again from your client in the Google Cloud console.'
  if (code === 'unauthorized_client')
    return 'This sign-in was made for another OAuth client: use the Client ID and secret it was made with, or sign in again.'
  if (code === 'redirect_uri_mismatch')
    return 'Google refused the Redirect URI. Make a client of the type "Desktop app", which takes http://127.0.0.1 on any port, and sign in again.'
  if (code === 'invalid_grant' && grant === 'refresh_token')
    return 'Google ended this sign-in. An app still in Testing gets sign-ins that end after 7 days: publish yours (Audience, Publish app) and sign in again.'
  if (code === 'invalid_grant')
    return 'That sign-in address was used already or is too old (it works once, for a few minutes). Sign in again and paste the new one.'
  if (status === 429) return 'Google asks to wait a little before the next sign-in.'
  return `Google refused the sign-in: ${said || code || `HTTP ${status}`}`
}

function fromToken(s: Settings, data: any, old: Auth, code: string): Auth {
  const auth: Auth = {
    client: s.clientId,
    access: String(data.access_token),
    expires: Date.now() + Math.max(60, Number(data.expires_in) || 3600) * 1000,
    // Google sends a refresh token with a sign-in, and keeps it on a refresh;
    // when it does send a new one, the new one is kept.
    refresh: String(data.refresh_token || old.refresh || ''),
    code,
  }
  const lasts = Number(data.refresh_token_expires_in)
  if (lasts > 0) auth.ends = Date.now() + lasts * 1000
  else if (!data.refresh_token && old.ends) auth.ends = old.ends
  return auth
}

export type Session = {
  token: string
  // Signed in, perhaps with a problem for the moment: no network. Otherwise the
  // sign-in screen shows, with the problem when there is one.
  signedIn: boolean
  problem: string
}

// Trades a pasted address (or token) for a sign-in, and an old access token
// for a new one. `force` makes a new one even when the last has time left
// (after a 401).
export function session(app, s: Settings, force = false): Session {
  let auth = readAuth(app)
  if (auth.client && auth.client !== s.clientId) auth = { code: auth.code }

  const pasted = s.signIn
  const token = pasted ? refreshFrom(pasted) : ''
  const code = pasted && !token ? codeFrom(pasted) : ''
  const given = token || code
  if (pasted && (!given || given !== auth.code)) {
    const granted = scopeIn(pasted)
    if (token) {
      // Checked by the refresh below: a token that does not work says so there.
      auth = { client: s.clientId, refresh: token, code: token }
    } else if (code && granted && !granted.split(/[ ,]+/).includes(SCOPE)) {
      auth = { ...auth, code, error: 'The frame was not allowed to see your tasks. Sign in again and tick "Create, edit, organize, and delete all your tasks".' }
    } else if (code) {
      const reply = tokenRequest(s, { grant_type: 'authorization_code', code, redirect_uri: s.redirectUri })
      if (reply.ok) auth = fromToken(s, reply.data, {}, code)
      // A failed new sign-in keeps one that works.
      else if (reply.code || reply.status) auth = { ...auth, code, error: reply.error }
      else return { token: '', signedIn: !!auth.refresh, problem: reply.error || '' }
    } else {
      auth = {
        ...auth,
        error: deniedIn(pasted)
          ? 'You did not let the frame in on Google\'s page. Sign in again and press "Continue".'
          : 'The Sign-in address has no code in it: paste the whole address the browser ended on after "Continue".',
      }
    }
    writeAuth(auth)
    frameos.setState('signIn', '')
  }

  if (!auth.refresh) return { token: '', signedIn: false, problem: auth.error || '' }
  if (!force && auth.access && (auth.expires || 0) > Date.now() + 60000)
    return { token: auth.access, signedIn: true, problem: '' }

  const reply = tokenRequest(s, { grant_type: 'refresh_token', refresh_token: auth.refresh })
  if (reply.ok) {
    auth = fromToken(s, reply.data, auth, auth.code || '')
    writeAuth(auth)
    return { token: auth.access!, signedIn: true, problem: '' }
  }
  if (reply.code === 'invalid_grant' || reply.code === 'invalid_client' || reply.code === 'unauthorized_client') {
    writeAuth({ client: s.clientId, code: auth.code, error: reply.error })
    return { token: '', signedIn: false, problem: reply.error || '' }
  }
  return { token: '', signedIn: true, problem: reply.error || 'Could not reach Google' }
}

// ---------------------------------------------------------------- the Tasks API

export type Reply = { status: number; data?: any; error?: string; reason?: string }
export type Client = { app: any; s: Settings; token: string }

// Google's "slow down": no call until then (frameos.remember, so it holds
// across renders and on a board that starts each render afresh).
export const waitUntil = () => Number(frameos.recall('wait') || 0)
const slowDown = (seconds: number) =>
  `Google asked the frame to slow down: it asks again in ${seconds < 120 ? `${seconds} s` : `${Math.ceil(seconds / 60)} min`}.`

const RATE_REASONS = ['rateLimitExceeded', 'userRateLimitExceeded', 'RATE_LIMIT_EXCEEDED', 'quotaExceeded', 'RESOURCE_EXHAUSTED']

export function call(client: Client, method: string, path: string, body?: any, retried = false): Reply {
  const wait = waitUntil()
  if (wait > Date.now()) return { status: 429, error: slowDown(Math.ceil((wait - Date.now()) / 1000)) }
  const reply = frameos.httpRequest(API + path, {
    method,
    headers: {
      Authorization: `Bearer ${client.token}`,
      Accept: 'application/json',
      ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    timeoutMs: 10000,
  })
  if (!reply.status) return { status: 0, error: `Could not reach Google: ${reply.error || 'no answer'}` }
  if (reply.status === 401 && !retried) {
    const again = session(client.app, client.s, true)
    if (!again.token) return { status: 401, error: again.problem || 'Signed out of Google' }
    client.token = again.token
    return call(client, method, path, body, true)
  }
  let data: any = null
  try {
    data = reply.body ? JSON.parse(reply.body) : null
  } catch (e) {
    data = null
  }
  if (reply.status >= 400) {
    const error = data?.error
    const message = typeof error === 'object' ? String(error?.message || '') : String(error || '')
    const reason = reasonOf(error)
    if (reply.status === 429 || (reply.status === 403 && RATE_REASONS.includes(reason))) {
      const seconds = Math.min(900, Math.max(30, Number(reply.headers?.['retry-after']) || 60))
      frameos.remember('wait', Date.now() + seconds * 1000)
      return { status: 429, error: slowDown(seconds), reason }
    }
    return { status: reply.status, error: apiProblem(reply.status, message, reason), reason }
  }
  return { status: reply.status, data }
}

// Google says why in error.errors[].reason (older) or an ErrorInfo's reason
// in error.details (newer), else error.status.
function reasonOf(error: any): string {
  if (!error || typeof error !== 'object') return ''
  const first = Array.isArray(error.errors) ? error.errors[0] : null
  if (first?.reason) return String(first.reason)
  const info = Array.isArray(error.details) ? error.details.find((d) => d && d.reason) : null
  if (info?.reason) return String(info.reason)
  return String(error.status || '')
}

function apiProblem(status: number, message: string, reason: string) {
  if (reason === 'SERVICE_DISABLED' || reason === 'accessNotConfigured' || /has not been used in project|is disabled/i.test(message))
    return 'The Google Tasks API is off in your Google Cloud project: turn it on (APIs & Services, Library, Google Tasks API, Enable) and wait a minute.'
  if (reason === 'ACCESS_TOKEN_SCOPE_INSUFFICIENT' || reason === 'insufficientPermissions' || /insufficient authentication scopes/i.test(message))
    return 'This sign-in may not see your tasks. Sign in again and allow Google Tasks.'
  if (status === 404) return 'Google Tasks did not find that list or task: it was deleted, or moved.'
  if (status >= 500) return `Google Tasks is having trouble (HTTP ${status}): the frame tries again soon.`
  return `Google Tasks answered: ${message || `HTTP ${status}`}`
}

