// The list on the frame: what is kept of it, how it is read from Google,
// the order it shows in, and the ticks a tap sends.
//
// The last good list is scene state, kept on the frame's disk (the private
// `cache` field), so a frame that restarts without a network, or whose
// sign-in ran out, still shows it under the problem. Only what is drawn is
// kept: a task's id, title, due date, parent and whether it was ticked here.
import { call } from './google'
import type { Client } from './google'

export type Task = { id: string; title: string; due: string; parent: string; done?: boolean }
export type List = { id: string; title: string }
export type Cache = {
  at: number
  // The Task list setting it was read for, and the list that was.
  wanted: string
  list: List
  lists: List[]
  listsAt: number
  // Open tasks, top-level ones by Google's order, each followed by its subtasks.
  tasks: Task[]
  // More open tasks than were read.
  more?: boolean
}

// What a page of tasks may hold, and how many lists are read: a frame keeps
// what it draws.
export const MAX_TASKS = 100
const LISTS_EVERY_MS = 6 * 3600 * 1000
const TITLE_MAX = 300

export function readCache(app): Cache | null {
  let kept = app.state.cache
  if (typeof kept === 'string') {
    try {
      kept = kept ? JSON.parse(kept) : null
    } catch (e) {
      kept = null
    }
  }
  return kept && typeof kept === 'object' && Array.isArray(kept.tasks) ? kept : null
}
export const writeCache = (cache: Cache) => frameos.setState('cache', cache as any)

// The list the Task list setting names (by its name, any case), else the first.
export function pickList(lists: List[], wanted: string): { list: List | null; missing: boolean } {
  const name = wanted.trim().toLowerCase()
  if (name) {
    const named = lists.find((list) => list.title.trim().toLowerCase() === name)
    if (named) return { list: named, missing: false }
  }
  return { list: lists[0] || null, missing: !!name && lists.length > 0 }
}

export function slimLists(data: any): List[] {
  const items = Array.isArray(data?.items) ? data.items : []
  return items
    .filter((item) => item && item.id)
    .slice(0, 50)
    .map((item) => ({ id: String(item.id), title: String(item.title || 'Untitled list') }))
}

// Google's due is an RFC 3339 time whose date alone means anything
// ("2026-12-01T00:00:00.000Z": the 1st, wherever the frame is). The date is
// read off the text, never through a Date in the frame's zone, which west of
// Greenwich would make it the 30th.
export const dueDate = (due: any) => (typeof due === 'string' && /^\d{4}-\d{2}-\d{2}/.test(due) ? due.slice(0, 10) : '')

// Open tasks in the order Google's apps show them ("My order"): top-level
// tasks by `position`, each followed by its subtasks by theirs. A subtask
// whose parent is not open (ticked off elsewhere) is shown at the top level,
// after the rest.
export function slimTasks(data: any): Task[] {
  const items = Array.isArray(data?.items) ? data.items : []
  const open = items.filter((item) => item && item.id && String(item.title || '').trim() && item.status !== 'completed' && !item.deleted)
  const pos = (item) => String(item.position || '')
  const byPos = (a, b) => (pos(a) < pos(b) ? -1 : pos(a) > pos(b) ? 1 : 0)
  const ids: Record<string, boolean> = {}
  for (const item of open) ids[item.id] = true
  const top = open.filter((item) => !item.parent).sort(byPos)
  const orphans = open.filter((item) => item.parent && !ids[item.parent]).sort(byPos)
  const slim = (item, parent: string): Task => ({
    id: String(item.id),
    title: String(item.title).trim().slice(0, TITLE_MAX),
    due: dueDate(item.due),
    parent,
  })
  const out: Task[] = []
  for (const item of top) {
    out.push(slim(item, ''))
    for (const child of open.filter((other) => other.parent === item.id).sort(byPos)) out.push(slim(child, String(item.id)))
  }
  for (const item of orphans) out.push(slim(item, ''))
  return out
}

// "By date": the same groups (a task and its subtasks), the ones due soonest
// first and those with no date last, each group in its own order.
export function byDate(tasks: Task[]): Task[] {
  const groups: Task[][] = []
  for (const task of tasks) {
    if (!task.parent || !groups.length) groups.push([task])
    else groups[groups.length - 1].push(task)
  }
  const key = (group: Task[]) => group[0].due || '9999-99-99'
  return groups
    .map((group, index) => ({ group, index }))
    .sort((a, b) => (key(a.group) < key(b.group) ? -1 : key(a.group) > key(b.group) ? 1 : a.index - b.index))
    .flatMap((entry) => entry.group)
}

export type Read = { cache: Cache | null; problem: string; missing?: string }

// Reads the lists (when not known, or every few hours) and the open tasks of
// the one wanted. A failure keeps what was kept and says why.
export function refresh(client: Client, kept: Cache | null, wanted: string): Read {
  let lists = kept?.lists || []
  let listsAt = kept?.listsAt || 0
  const known = pickList(lists, wanted)
  if (!lists.length || Date.now() - listsAt > LISTS_EVERY_MS || known.missing) {
    const reply = call(client, 'GET', '/users/@me/lists?maxResults=50&fields=items(id,title)')
    if (reply.status !== 200) return { cache: kept, problem: reply.error || `HTTP ${reply.status}` }
    lists = slimLists(reply.data)
    listsAt = Date.now()
  }
  const { list, missing } = pickList(lists, wanted)
  if (!list) return { cache: kept, problem: 'This Google account has no task lists yet: make one in Google Tasks.' }
  const path = `/lists/${encodeURIComponent(list.id)}/tasks?showCompleted=false&showHidden=false&maxResults=${MAX_TASKS}` +
    '&fields=items(id,title,status,due,parent,position),nextPageToken'
  const reply = call(client, 'GET', path)
  if (reply.status === 404) {
    // The list went: read the lists again next time.
    if (kept) kept.listsAt = 0
    return { cache: kept, problem: reply.error || 'HTTP 404' }
  }
  if (reply.status !== 200) return { cache: kept, problem: reply.error || `HTTP ${reply.status}` }
  const cache: Cache = {
    at: Date.now(),
    wanted,
    list,
    lists,
    listsAt,
    tasks: slimTasks(reply.data),
    more: !!reply.data?.nextPageToken,
  }
  return { cache, problem: '', missing: missing ? wanted.trim() : '' }
}

// ---------------------------------------------------------------- ticks

// The tasks a tick on `task` moves with it: its subtasks that were as it
// was (Google's own apps tick a task's subtasks off with it).
export function tickedWith(tasks: Task[], task: Task, done: boolean): Task[] {
  const along = task.parent ? [] : tasks.filter((other) => other.parent === task.id && !!other.done !== done)
  return [task, ...along]
}

export type Ticked = { changed: Task[]; problem: string }

// Ticks a task off (`done`) or reopens it, with its subtasks: in the kept
// list first, then at Google, one PATCH a task (status completed, or back to
// needsAction). What Google refuses is put back as it was; when that is the
// task tapped, so are its subtasks. Ticked tasks stay in the kept list,
// struck through, until the next read leaves them out.
export function tick(client: Client, cache: Cache, id: string, done: boolean): Ticked {
  const task = cache.tasks.find((other) => other.id === id)
  if (!task || !!task.done === done) return { changed: [], problem: '' }
  const moving = tickedWith(cache.tasks, task, done)
  const before = moving.map((one) => one.done)
  for (const one of moving) one.done = done
  writeCache(cache)
  const changed: Task[] = []
  let problem = ''
  for (let i = 0; i < moving.length; i++) {
    const one = moving[i]
    const body = done ? { status: 'completed' } : { status: 'needsAction', completed: null }
    const reply = call(client, 'PATCH', `/lists/${encodeURIComponent(cache.list.id)}/tasks/${encodeURIComponent(one.id)}`, body)
    if (reply.status >= 200 && reply.status < 300) {
      changed.push(one)
      continue
    }
    problem = `Could not ${done ? 'tick off' : 'reopen'} "${one.title}". ${reply.error || `HTTP ${reply.status}`}`
    if (i === 0) {
      moving.forEach((other, j) => (other.done = before[j]))
      break
    }
    one.done = before[i]
  }
  writeCache(cache)
  return { changed, problem }
}

// ---------------------------------------------------------------- due dates

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

// Today in the frame's zone, as Google writes dates.
export function todayOf(now: number) {
  const d = new Date(now)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}
const dayNumber = (date: string) => Math.round(Date.UTC(Number(date.slice(0, 4)), Number(date.slice(5, 7)) - 1, Number(date.slice(8, 10))) / 86400000)

export type Due = { text: string; late: boolean; today: boolean }

// As short as it reads: Today, Tomorrow, Yesterday, a weekday within the
// week ahead, else Dec 3 (and the year when it is another).
export function dueLabel(due: string, today: string): Due | null {
  if (!due) return null
  const days = dayNumber(due) - dayNumber(today)
  const late = days < 0
  if (days === 0) return { text: 'Today', late, today: true }
  if (days === 1) return { text: 'Tomorrow', late, today: false }
  if (days === -1) return { text: 'Yesterday', late, today: false }
  const weekday = DAYS[(((dayNumber(due) + 4) % 7) + 7) % 7]
  if (days > 1 && days < 7) return { text: weekday, late, today: false }
  const month = MONTHS[Number(due.slice(5, 7)) - 1] || ''
  const day = String(Number(due.slice(8, 10)))
  const year = due.slice(0, 4) !== today.slice(0, 4) ? ` ${due.slice(0, 4)}` : ''
  return { text: `${month} ${day}${year}`, late, today: false }
}

