// The parts of the scene that know nothing of Google: the looks, sizes worked
// out from the canvas, icons and the setup screens. app.tsx decides what
// shows; this file only draws.

// ---------------------------------------------------------------- looks

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
export const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  // Light, with Google's blue for what is due today and ticked, and red for
  // what is late.
  color: {
    high: false,
    page: 'bg-[#f6f8fc] text-[#1f1f1f]',
    side: 'bg-[#e8eef8] text-[#1f1f1f]',
    muted: 'text-[#5e6470]',
    accent: 'text-[#0b57d0]',
    late: 'text-[#b3261e]',
    card: 'bg-white',
    line: 'border-b border-[#e3e6ec]',
    circle: 'border-2 border-[#6b7280]',
    circleOn: 'bg-[#0b57d0] text-white',
    doneText: 'text-[#8a909a] line-through',
    chip: 'bg-[#eef1f6] text-[#3c4350]',
    chipToday: 'bg-[#d3e3fd] text-[#0b57d0]',
    chipLate: 'bg-[#fce8e6] text-[#b3261e]',
    button: 'text-[#3c4350] active:bg-[#dfe6f1]',
    pill: 'bg-white text-[#1f1f1f] active:bg-[#dfe6f1]',
    pillOn: 'bg-[#0b57d0] text-white',
    primary: 'bg-[#0b57d0] text-white active:bg-[#0842a0]',
    banner: 'bg-[#fce8e6] text-[#8c1d18]',
    code: 'bg-[#eef1f6] text-[#0b57d0]',
    step: 'bg-[#0b57d0] text-white',
    ring: '#0b57d0',
    ringTrack: '#d3e3fd',
  },
  // Black on white, borders for cards, black fills for what is on: no greys
  // to dither on e-paper.
  high: {
    high: true,
    page: 'bg-white text-black',
    side: 'bg-white text-black border-r-2 border-black',
    muted: 'text-black',
    accent: 'text-black',
    late: 'text-black',
    card: 'bg-white border-2 border-black',
    line: 'border-b-2 border-black',
    circle: 'border-2 border-black',
    circleOn: 'bg-black text-white',
    doneText: 'text-black line-through',
    chip: 'bg-white text-black border-2 border-black',
    chipToday: 'bg-white text-black border-2 border-black font-bold',
    chipLate: 'bg-black text-white font-bold',
    button: 'text-black',
    pill: 'bg-white text-black border-2 border-black',
    pillOn: 'bg-black text-white border-2 border-black',
    primary: 'bg-black text-white',
    banner: 'bg-black text-white',
    code: 'bg-white text-black border-2 border-black',
    step: 'bg-black text-white',
    ring: '#000000',
    ringTrack: '#ffffff',
  },
}
// Color e-paper (a Spectra's six inks): the high-contrast page with the ticks
// and the buttons in the panel's own blue and what is late in its red, as the
// panel shows them, so nothing is dithered into confetti.
const INKS = {
  ...THEMES.high,
  accent: 'text-[#18539a]',
  late: 'text-[#6b1119]',
  circleOn: 'bg-[#18539a] text-white',
  chipToday: 'bg-[#18539a] text-white font-bold',
  chipLate: 'bg-[#6b1119] text-white font-bold',
  pillOn: 'bg-[#18539a] text-white border-2 border-[#18539a]',
  primary: 'bg-[#18539a] text-white',
  banner: 'bg-[#6b1119] text-white',
  code: 'bg-white text-[#18539a] border-2 border-[#18539a]',
  step: 'bg-[#18539a] text-white',
  ring: '#18539a',
}
export type Theme = typeof THEMES.color
export const themeOf = (app): Theme => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return INKS
  return THEMES.color
}

// Every length comes from the canvas: drawn for about 480 px on the shorter
// side, smaller on a small screen (a 2.8" LCD, a watch), and on a panel of
// 900 px or more (a 13.3" color e-paper at render scale 1) that much larger,
// by halves, so the list fills it. s(16) is what 16 px is on this frame.
export function sizesOf(W: number, H: number, scale = 0) {
  const short = Math.min(W, H)
  const k = scale || (short >= 900 ? Math.min(3, Math.floor((short / 480) * 2) / 2) : short < 360 ? Math.max(0.75, short / 400) : 1)
  const s = (px: number) => Math.max(1, Math.round(px * k))
  return { W, H, k, s, small: short < 360 }
}
export type Sizes = ReturnType<typeof sizesOf>

export const clamp = (value: number, low: number, high: number) => Math.max(low, Math.min(high, value))

